INSERT INTO data_sample (
    uuid, point_id, sample_value, sample_unit, sample_time, device_id,
    calibration_value, status, create_by, create_time, update_by, update_time, note, is_del
) VALUES (
             CAST(#{uuid} AS uuid), #{pointId}, #{sampleValue}, #{sampleUnit}, #{sampleTime}, #{deviceId},
             #{calibrationValue}, #{status}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{note}, #{isDel}
         )
